use std::net::SocketAddr;

use opentelemetry::global;
use opentelemetry::propagation::Extractor;
use opentelemetry::trace::{SpanKind, Tracer};
use opentelemetry::KeyValue;
use opentelemetry_otlp::{SpanExporter, WithExportConfig};
use opentelemetry_sdk::propagation::TraceContextPropagator;
use opentelemetry_sdk::trace::SdkTracerProvider;
use opentelemetry_sdk::Resource;
use tonic::metadata::{KeyRef, MetadataMap as TonicMetadataMap};
use tonic::{transport::Server, Request, Response, Status};

// Generated by build.rs into src/proto/. Committed so reviewers see the wire
// shape without running cargo first.
pub mod hello {
    include!("proto/hello.rs");
}
use hello::greeter_server::{Greeter, GreeterServer};
use hello::{HelloReply, HelloRequest};

type BoxError = Box<dyn std::error::Error + Send + Sync>;

/// Build the OTel tracer provider, install W3C as the global propagator,
/// register the provider globally, and return it so `main` can shut it
/// down cleanly. Modelled on opentelemetry-rust/examples/tracing-grpc.
fn init_tracer() -> Result<SdkTracerProvider, BoxError> {
    global::set_text_map_propagator(TraceContextPropagator::new());

    let endpoint = std::env::var("OTEL_EXPORTER_OTLP_ENDPOINT")
        .unwrap_or_else(|_| "http://otel-collector:4317".to_string());

    let exporter = SpanExporter::builder()
        .with_tonic()
        .with_endpoint(endpoint)
        .build()?;

    let provider = SdkTracerProvider::builder()
        .with_batch_exporter(exporter)
        .with_resource(Resource::builder().with_service_name("server").build())
        .build();

    global::set_tracer_provider(provider.clone());
    Ok(provider)
}

/// Adapter: lets the OTel propagator read gRPC headers off a tonic
/// `MetadataMap`. Inlined from the upstream example.
struct MetadataMap<'a>(&'a TonicMetadataMap);

impl Extractor for MetadataMap<'_> {
    fn get(&self, key: &str) -> Option<&str> {
        self.0.get(key).and_then(|v| v.to_str().ok())
    }
    fn keys(&self) -> Vec<&str> {
        self.0
            .keys()
            .map(|k| match k {
                KeyRef::Ascii(v) => v.as_str(),
                KeyRef::Binary(v) => v.as_str(),
            })
            .collect()
    }
}

struct GreeterSvc;

#[tonic::async_trait]
impl Greeter for GreeterSvc {
    async fn say_hello(&self, req: Request<HelloRequest>) -> Result<Response<HelloReply>, Status> {
        // Extract the upstream W3C context off the incoming metadata, then
        // start a server-kind span as a child of it. The named `_span`
        // binding keeps the span alive until end-of-scope — binding to bare
        // `_` would drop it immediately and record zero duration.
        let parent_cx =
            global::get_text_map_propagator(|p| p.extract(&MetadataMap(req.metadata())));
        let tracer = global::tracer("server");
        let _span = tracer
            .span_builder("Greeter/say_hello")
            .with_kind(SpanKind::Server)
            .with_attributes([
                KeyValue::new("rpc.system", "grpc"),
                KeyValue::new("rpc.method", "say_hello"),
            ])
            .start_with_context(&tracer, &parent_cx);

        let name = req.into_inner().name;
        let name = if name.is_empty() { "world" } else { &name };
        Ok(Response::new(HelloReply {
            message: format!("hello, {name}"),
        }))
    }
}

#[tokio::main]
async fn main() -> Result<(), BoxError> {
    let provider = init_tracer()?;

    let addr: SocketAddr = std::env::var("SERVER_ADDR")
        .unwrap_or_else(|_| "0.0.0.0:50051".to_string())
        .parse()?;
    println!("server: listening on {addr}");

    Server::builder()
        .add_service(GreeterServer::new(GreeterSvc))
        .serve(addr)
        .await?;

    provider.shutdown()?;
    Ok(())
}
